18	var pathIPv6Text = capitalize(errPathIPv6.Error())
19	
20	// traceFormWithTarget returns a supported model whose target field holds value.
21	func traceFormWithTarget(t *testing.T, value string) (*Model, *fakeEngine) {
22		t.Helper()
23		m, fe := traceFormModel(t, true)
24		m.targetInput.SetValue(value)
25		return m, fe
26	}
27	
28	// pressTrace focuses the Trace Path button and presses enter.
29	func pressTrace(t *testing.T, m *Model) *Model {
30		t.Helper()
31		m.focusedField = fieldTraceButton
32		return feed(t, m, testutil.Key("enter"))
33	}
34	
35	// footerError is the status the Diagnostics tab derives on this frame.
36	func footerError(m *Model) (string, components.Level) {
37		_, st := m.activeFooter()
38		return st.Text, st.Level
39	}
40	
41	func TestTraceFormValidationRefusesAnInvalidTarget(t *testing.T) {
42		tests := []struct {
43			name, target, want string
44		}{
45			{"empty", "", "Target is required"},
46			{"ipv6 literal", "::1", pathIPv6Text},
47			{"host with port", "host:8080", errPathPortText},
48			{"bracketed ipv6 with port", "[::1]:443", errPathPortText},
49			{"malformed host", "bad host!", "Target must be a hostname or IP address"},
50		}
51		for _, tc := range tests {
52			t.Run(tc.name, func(t *testing.T) {
53				m, fe := traceFormWithTarget(t, tc.target)
54				gen := m.pathModel.gen
55				m = pressTrace(t, m)
56	
57				if m.state != StateInput {
58					t.Errorf("state = %v, want StateInput", m.state)
59				}
60				if m.pathModel.gen != gen || fe.traceCalls != 0 || fe.resolveCalls != 0 {
61					t.Errorf("gen %d->%d trace=%d resolve=%d, nothing may be emitted",
62						gen, m.pathModel.gen, fe.traceCalls, fe.resolveCalls)
63				}
64				if !m.traceValidation.Invalid(traceKeyTarget) {
65					t.Error("the target is not marked invalid")
66				}
67				if !strings.Contains(m.targetInput.View(), curlyUnderline) {
68					t.Errorf("the target is not underlined: %q", m.targetInput.View())
69				}
70				text, level := footerError(m)
71				if text != tc.want || level != components.LevelError {
72					t.Errorf("footer = {%q %v}, want {%q Error}", text, level, tc.want)
73				}
74				if !strings.Contains(m.RenderFooter(120), tc.want) {
75					t.Errorf("RenderFooter does not show %q", tc.want)
76				}
77			})
78		}
