83		for _, target := range []string{"", "::1", "host:8080", "[::1]:443", "bad host!"} {
84			_, err := parsePathTarget(target)
85			if err == nil {
86				t.Fatalf("parsePathTarget(%q) accepted the target", target)
87			}
