111	
112		if text, level := footerError(m); text != errPathPortText || level != components.LevelError {
113			t.Errorf("after the footer expiry: {%q %v}, want {%q Error}", text, level, errPathPortText)
114		}
115		if !strings.Contains(m.targetInput.View(), curlyUnderline) {
116			t.Error("the underline went away with the footer timer")
117		}
118	}
119	
120	func TestTraceFormValidationCorrectionClearsTheMarks(t *testing.T) {
121		corrections := map[string]func(*testing.T, *Model) *Model{
122			"typing": func(t *testing.T, m *Model) *Model {
123				m.targetInput.SetValue("example")
124				m.targetInput.CursorEnd()
125				return typeInto(t, m, ".com")
126			},
127			"paste": func(t *testing.T, m *Model) *Model {
128				m.targetInput.SetValue("")
129				m.focusedField = fieldTarget
130				m.targetInput.Focus()
131				return feed(t, m, testutil.Paste("example.com"))
132			},
133		}
134		for name, correct := range corrections {
135			t.Run(name, func(t *testing.T) {
136				m, _ := traceFormWithTarget(t, "host:8080")
137				m = pressTrace(t, m)
138				if !m.traceValidation.Invalid(traceKeyTarget) {
139					t.Fatal("precondition: the refused trace must mark the target")
140				}
141	
142				m = correct(t, m)
143				if m.traceValidation.Invalid(traceKeyTarget) {
144					t.Error("the target is still marked invalid after the correction")
145				}
146				if strings.Contains(m.targetInput.View(), curlyUnderline) {
147					t.Error("the target is still underlined after the correction")
148				}
149				if text, _ := footerError(m); text != "" {
150					t.Errorf("footer = %q after the correction, want empty", text)
151				}
152			})
153		}
154	}
155	
156	// Revalidation stays live: breaking the target again shows at once.
157	func TestTraceFormValidationStaysLiveAfterARefusal(t *testing.T) {
158		m, _ := traceFormWithTarget(t, "")
159		m = pressTrace(t, m)
160		m = typeInto(t, m, "host:80")
161		if !m.traceValidation.Invalid(traceKeyTarget) {
162			t.Error("typing a port after a refusal did not mark the target")
163		}
164		if text, _ := footerError(m); text != errPathPortText {
165			t.Errorf("footer = %q, want %q", text, errPathPortText)
166		}
167	}
168	
169	func TestTraceFormValidationAcceptedRunClearsTheError(t *testing.T) {
170		m, _ := traceFormWithTarget(t, "host:8080")
171		m = pressTrace(t, m)
172		if !m.traceValidation.Invalid(traceKeyTarget) {
173			t.Fatal("precondition: the refused trace must mark the target")
174		}
175	
176		m.targetInput.SetValue("example.com")
177		m.focusedField = fieldRunButton
178		m = feed(t, m, testutil.Key("enter"))
179	
180		if m.state != StateRunning {
181			t.Fatalf("state = %v, want StateRunning", m.state)
182		}
183		if m.traceValidation.Invalid(traceKeyTarget) {
184			t.Error("an accepted run left the target marked invalid")
185		}
186		if strings.Contains(m.targetInput.View(), curlyUnderline) {
187			t.Error("an accepted run left the target underlined")
188		}
189		if text, _ := footerError(m); text != "" {
190			t.Errorf("footer = %q after an accepted run, want empty", text)
191		}
192	}
193	
194	func TestTraceFormValidationValidTargetPassesTheGate(t *testing.T) {
195		m, _ := traceFormWithTarget(t, "example.com")
196		m = pressTrace(t, m)
197		if m.traceValidation.Invalid(traceKeyTarget) || strings.Contains(m.targetInput.View(), curlyUnderline) {
198			t.Error("a valid target is marked invalid")
199		}
200		if text, _ := footerError(m); text != "" {
201			t.Errorf("footer = %q for a valid target, want empty", text)
202		}
203	}
204	
205	// traceMarks must be the InvalidMarks type, so a restyle only happens on a
206	// change of state (Rule 140).
207	func TestTraceFormValidationFieldTypes(t *testing.T) {
208		var _ components.Validation = (&Model{}).traceValidation
209		var _ components.InvalidMarks = (&Model{}).traceMarks
210	}
