1	package ociresources
2	
3	import (
4		"fmt"
5		"path/filepath"
6		"strconv"
7		"strings"
8	
9		"charm.land/bubbles/v2/textinput"
10		tea "charm.land/bubbletea/v2"
11	
12		"github.com/anthnel/devdesk/internal/cache"
13		"github.com/anthnel/devdesk/internal/docker"
14		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
15		"github.com/anthnel/devdesk/internal/ui/keymap"
16		"github.com/anthnel/devdesk/internal/ui/theme"
17	)
18	
19	// LaunchFormSubmitMsg is sent when the launch form is submitted
20	type LaunchFormSubmitMsg struct {
21		Opts docker.ContainerLaunchOptions
22	}
23	
24	// LaunchFormCancelMsg is sent when the launch form is cancelled
25	type LaunchFormCancelMsg struct{}
26	
27	// EntrypointVerifyFinishedMsg is sent when the background entrypoint verification completes.
28	// Seq guards against stale results from previous verification runs.
29	type EntrypointVerifyFinishedMsg struct {
30		Seq int
31		OK  bool
32	}
33	
34	// portEntry represents a port declared by EXPOSE in the image, with an editable host mapping.
35	type portEntry struct {
36		containerPort string          // e.g. "80/tcp" — fixed, from image EXPOSE
37		hostPortInput textinput.Model // editable host port number, defaults to the container port number
38		enabled       bool
39	}
40	
41	// containerPortNum returns the numeric part of containerPort (strips "/protocol" suffix).
42	func (p *portEntry) containerPortNum() string {
43		if idx := strings.Index(p.containerPort, "/"); idx > 0 {
44			return p.containerPort[:idx]
45		}
46		return p.containerPort
47	}
48	
49	// mappingArg returns the "-p host:container" argument value for docker run.
50	// Falls back to the container port number when the host input is empty.
51	func (p *portEntry) mappingArg() string {
52		host, ok := normalizeHostPort(p.hostPortInput.Value())
53		if !ok {
54			host = strings.TrimSpace(p.hostPortInput.Value()) // refused by validate() before it gets here
55		}
56		container := p.containerPortNum()
57		if host == "" {
58			host = container
59		}
60		return host + ":" + container
61	}
62	
63	// verifyState represents the entrypoint verification status
64	type verifyState int
65	
66	const (
67		verifyIdle     verifyState = iota // no entrypoint typed
68		verifyChecking                    // docker check in progress
69		verifyOK                          // binary found in image
70		verifyWarning                     // binary not found
71	)
72	
73	// commonShells lists base names that trigger auto-selection of Interactive/TTY mode
74	var commonShells = map[string]bool{
75		"sh": true, "bash": true, "zsh": true, "fish": true,
76		"dash": true, "ksh": true, "csh": true, "tcsh": true,
77		"ash": true, "python": true, "python3": true, "busybox": true,
78	}
79	
80	// LaunchForm is a viewport form for launching a container from an image
81	type LaunchForm struct {
82		image                string
83		nameInput            textinput.Model
84		ports                []portEntry     // one row per image EXPOSE port
85		extraPortsInput      textinput.Model // free-form extra port mappings (comma-separated host:container)
86		entrypointInput      textinput.Model
87		envInput             textinput.Model
88		volInput             textinput.Model
89		userInput            textinput.Model // --user UID:GID or username (optional)
90		networks             []string        // available Docker network names
91		networkIdx           int             // index into networks
92		optionRemove         bool            // --rm: remove container on exit
93		optionDetach         bool            // -d: run in background
94		optionInteractiveTTY bool            // -it: interactive + TTY
95		verify               verifyState
96		verifySeq            int    // incremented on each new verification to discard stale results
97		lastEntrypoint       string // tracks previous entrypoint value for change detection
98		focusedField         int
99		validation           sharedcomponents.Validation // host port errors, live after a refused submit (DEVDESK-292)
100		marks                sharedcomponents.InvalidMarks
101		width                int // viewport content width for two-column layout
102	}
103	
104	// NewLaunchForm creates a launch form pre-filled with exposed ports and available networks.
105	// exposedPorts is a slice of "port/protocol" strings, e.g. ["80/tcp", "443/tcp"].
106	func NewLaunchForm(imageName string, exposedPorts []string, networks []docker.Network, width int) *LaunchForm {
107		newInput := func(placeholder string) textinput.Model {
108			ti := textinput.New()
109			ti.CharLimit = 512
110			theme.StyleTextInput(&ti)
111			ti.Placeholder = placeholder
112			return ti
113		}
114	
115		nameInput := newInput("container-name (optional)")
116		entrypointInput := newInput("/bin/sh (optional override)")
117		envInput := newInput("APP_PORT=8080")
118		volInput := newInput("myvolume:/app/data")
119		userInput := newInput("1000:1000 or username (optional)")
120		extraPortsInput := newInput("8080:8080, 9090:9090")
121	
122		// Build port entries from image EXPOSE specs — all enabled by default
123		var ports []portEntry
124		for _, spec := range exposedPorts {
125			// spec = "80/tcp" or bare "80"
126			portNum := spec
127			if idx := strings.Index(spec, "/"); idx > 0 {
128				portNum = spec[:idx]
129			}
130			hi := textinput.New()
131			hi.CharLimit = 10
132			hi.SetWidth(6)
133			theme.StyleTextInput(&hi)
134			hi.SetValue(portNum)
135			ports = append(ports, portEntry{
136				containerPort: spec,
137				hostPortInput: hi,
138				enabled:       true,
139			})
140		}
141	
142		// Build network list, always include bridge as fallback
143		var netNames []string
144		seen := map[string]bool{}
145		for _, n := range networks {
146			if !seen[n.Name] {
147				netNames = append(netNames, n.Name)
148				seen[n.Name] = true
149			}
150		}
151		if len(netNames) == 0 {
152			netNames = []string{"bridge"}
153		}
154	
155		nameInput.Focus()
156	
157		f := &LaunchForm{
158			image:           imageName,
159			nameInput:       nameInput,
160			ports:           ports,
161			extraPortsInput: extraPortsInput,
162			entrypointInput: entrypointInput,
163			envInput:        envInput,
164			volInput:        volInput,
165			userInput:       userInput,
166			networks:        netNames,
167			optionDetach:    true, // default: run in background
168			width:           width,
169		}
170		f.resizeInputs()
171		return f
172	}
173	
174	// ToCacheEntry extracts the current form field values into a LaunchOptionsEntry for caching.
175	// The container name is intentionally excluded (must be unique per container).
176	func (f *LaunchForm) ToCacheEntry() cache.LaunchOptionsEntry {
177		portMappings := make(map[string]cache.PortMappingEntry, len(f.ports))
178		for _, p := range f.ports {
179			portMappings[p.containerPort] = cache.PortMappingEntry{
180				HostPort: p.hostPortInput.Value(),
181				Enabled:  p.enabled,
182			}
183		}
184		network := ""
185		if len(f.networks) > 0 {
186			network = f.networks[f.networkIdx]
187		}
188		return cache.LaunchOptionsEntry{
189			Entrypoint:   f.entrypointInput.Value(),
190			ExtraPorts:   f.extraPortsInput.Value(),
191			Env:          f.envInput.Value(),
192			Volumes:      f.volInput.Value(),
193			User:         f.userInput.Value(),
194			Network:      network,
195			Remove:       f.optionRemove,
196			Detach:       f.optionDetach,
197			Interactive:  f.optionInteractiveTTY,
198			PortMappings: portMappings,
199		}
200	}
201	
202	// ApplyCached pre-fills the form fields from a cached launch options entry.
203	func (f *LaunchForm) ApplyCached(entry cache.LaunchOptionsEntry) {
204		f.entrypointInput.SetValue(entry.Entrypoint)
205		f.lastEntrypoint = entry.Entrypoint
206		f.extraPortsInput.SetValue(entry.ExtraPorts)
207		f.envInput.SetValue(entry.Env)
208		f.volInput.SetValue(entry.Volumes)
209		f.userInput.SetValue(entry.User)
210		f.optionRemove = entry.Remove
211		f.optionDetach = entry.Detach
212		f.optionInteractiveTTY = entry.Interactive
213	
214		// Apply cached network selection by name
215		if entry.Network != "" {
216			for i, n := range f.networks {
217				if n == entry.Network {
218					f.networkIdx = i
219					break
220				}
221			}
222		}
223	
224		// Apply cached port mappings by container port key; unmatched ports keep defaults
225		for i := range f.ports {
226			if pm, ok := entry.PortMappings[f.ports[i].containerPort]; ok {
227				f.ports[i].hostPortInput.SetValue(pm.HostPort)
228				f.ports[i].hostPortInput.CursorEnd() // SetValue while blurred leaves a stale cursor
229				f.ports[i].enabled = pm.Enabled
230			}
231		}
232	}
233	
234	// GetTitle returns the form title for use in the viewport breadcrumb
235	func (f *LaunchForm) GetTitle() string { return "Launch Container" }
236	
237	// SetWidth updates the form width for responsive two-column rendering
238	func (f *LaunchForm) SetWidth(w int) {
239		f.width = w
240		f.resizeInputs()
241	}
242	
243	func (f *LaunchForm) resizeInputs() {
244		// In two-column mode the left column is 55% of width; inputs sit below their label with 2-char indent.
245		inputWidth := f.width - 4
246		if f.width >= 100 {
247			inputWidth = f.width*55/100 - 4
248		}
249		inputWidth = max(inputWidth, 20)
250		f.nameInput.SetWidth(inputWidth)
251		f.entrypointInput.SetWidth(inputWidth)
252		f.envInput.SetWidth(inputWidth)
253		f.volInput.SetWidth(inputWidth)
254		f.userInput.SetWidth(inputWidth)
255		f.extraPortsInput.SetWidth(inputWidth)
256	}
257	
258	// Field indices follow the visual render order:
259	// 0:name  1:entrypoint  2:env  3:volumes  4:user  5:network  6..6+n-1:ports  6+n:extraPorts  6+n+1..+3:options  6+n+4:submit
260	const firstPortFieldOffset = 6
261	
262	func (f *LaunchForm) fieldEntrypoint() int        { return 1 }
263	func (f *LaunchForm) fieldEnv() int               { return 2 }
264	func (f *LaunchForm) fieldVolumes() int           { return 3 }
265	func (f *LaunchForm) fieldUser() int              { return 4 }
266	func (f *LaunchForm) fieldNetwork() int           { return 5 }
267	func (f *LaunchForm) firstPortField() int         { return firstPortFieldOffset }
268	func (f *LaunchForm) fieldExtraPorts() int        { return firstPortFieldOffset + len(f.ports) }
269	func (f *LaunchForm) fieldOptionRemove() int      { return firstPortFieldOffset + len(f.ports) + 1 }
270	func (f *LaunchForm) fieldOptionDetach() int      { return firstPortFieldOffset + len(f.ports) + 2 }
271	func (f *LaunchForm) fieldOptionInteractive() int { return firstPortFieldOffset + len(f.ports) + 3 }
272	func (f *LaunchForm) fieldSubmit() int            { return firstPortFieldOffset + len(f.ports) + 4 }
273	
274	// isPortField returns true if the given index corresponds to a port entry row
275	func (f *LaunchForm) isPortField(idx int) bool {
276		return idx >= f.firstPortField() && idx < f.firstPortField()+len(f.ports)
277	}
278	
279	// Update handles messages for the launch form
280	func (f *LaunchForm) Update(msg tea.Msg) (*LaunchForm, tea.Cmd) {
281		switch msg := msg.(type) {
282		case tea.KeyPressMsg:
283			return f.handleKeyMsg(msg)
284		case EntrypointVerifyFinishedMsg:
285			return f.handleVerifyFinished(msg)
286		}
287		return f.updateActiveInput(msg)
288	}
289	
290	func (f *LaunchForm) handleKeyMsg(msg tea.KeyPressMsg) (*LaunchForm, tea.Cmd) {
291		maxField := f.fieldSubmit()
292	
293		switch msg.String() {
294		case "ctrl+y":
295			return f, copyToClipboardCmd(f.buildCommandString())
296	
297		case "esc":
298			return f, func() tea.Msg { return LaunchFormCancelMsg{} }
299	
300		case "down":
301			f.focusedField = (f.focusedField + 1) % (maxField + 1)
302			f.updateFocus()
303			return f, nil
304	
305		case "up":
306			f.focusedField = (f.focusedField - 1 + maxField + 1) % (maxField + 1)
307			f.updateFocus()
308			return f, nil
309	
310		case "left":
311			if f.focusedField == f.fieldNetwork() && len(f.networks) > 0 {
312				f.networkIdx = (f.networkIdx - 1 + len(f.networks)) % len(f.networks)
313				return f, nil
314			}
315		case "right":
316			if f.focusedField == f.fieldNetwork() && len(f.networks) > 0 {
317				f.networkIdx = (f.networkIdx + 1) % len(f.networks)
318				return f, nil
319			}
320	
321		case keymap.Space:
322			// Space toggles checkboxes (Rule 135): port fields and option checkboxes
323			if f.isPortField(f.focusedField) {
324				f.ports[f.focusedField-f.firstPortField()].enabled = !f.ports[f.focusedField-f.firstPortField()].enabled
325				f.revalidate()
326				return f, nil
327			}
328			if f.isOptionField(f.focusedField) {
329				return f.handleSpaceKey()
330			}
331			// A text field takes the space as a character (DEVDESK-266).
332			return f.updateActiveInput(msg)
333	
334		case "enter":
335			// Enter advances to next field or submits; never toggles (Rule 135)
336			return f.handleEnterKey()
337		}
338	
339		return f.updateActiveInput(msg)
340	}
341	
342	// handleEnterKey processes Enter: advances to next field or submits (Rule 135 — never toggles).
343	func (f *LaunchForm) handleEnterKey() (*LaunchForm, tea.Cmd) {
344		maxField := f.fieldSubmit()
345		if f.focusedField == maxField {
346			return f.submit()
347		}
348		f.focusedField = (f.focusedField + 1) % (maxField + 1)
349		f.updateFocus()
350		return f, nil
351	}
352	
353	// isOptionField reports whether a field is one of the option checkboxes.
354	func (f *LaunchForm) isOptionField(field int) bool {
355		return field == f.fieldOptionRemove() || field == f.fieldOptionDetach() ||
356			field == f.fieldOptionInteractive()
357	}
358	
359	// handleSpaceKey processes Space: toggles option checkboxes (Rule 135).
360	func (f *LaunchForm) handleSpaceKey() (*LaunchForm, tea.Cmd) {
361		if f.focusedField == f.fieldOptionRemove() {
362			f.optionRemove = !f.optionRemove
363			return f, nil
364		}
365		if f.focusedField == f.fieldOptionDetach() {
366			f.optionDetach = !f.optionDetach
367			if f.optionDetach {
368				f.optionInteractiveTTY = false
369			}
370			return f, nil
371		}
372		if f.focusedField == f.fieldOptionInteractive() {
373			f.optionInteractiveTTY = !f.optionInteractiveTTY
374			if f.optionInteractiveTTY {
375				f.optionDetach = false
376			}
377			return f, nil
378		}
379		return f, nil
380	}
381	
382	// handleVerifyFinished updates the verify state, discarding stale results
383	func (f *LaunchForm) handleVerifyFinished(msg EntrypointVerifyFinishedMsg) (*LaunchForm, tea.Cmd) {
384		if msg.Seq != f.verifySeq {
385			return f, nil // stale result from a previous entrypoint value
386		}
387		if msg.OK {
388			f.verify = verifyOK
389		} else {
390			f.verify = verifyWarning
391		}
392		return f, nil
393	}
394	
395	func (f *LaunchForm) updateFocus() {
396		f.nameInput.Blur()
397		f.extraPortsInput.Blur()
398		f.entrypointInput.Blur()
399		f.envInput.Blur()
400		f.volInput.Blur()
401		f.userInput.Blur()
402		for i := range f.ports {
403			f.ports[i].hostPortInput.Blur()
404		}
405		switch {
406		case f.focusedField == 0:
407			f.nameInput.Focus()
408		case f.isPortField(f.focusedField):
409			in := &f.ports[f.focusedField-f.firstPortField()].hostPortInput
410			in.Focus()
411		case f.focusedField == f.fieldExtraPorts():
412			f.extraPortsInput.Focus()
413		case f.focusedField == f.fieldEntrypoint():
414			f.entrypointInput.Focus()
415		case f.focusedField == f.fieldEnv():
416			f.envInput.Focus()
417		case f.focusedField == f.fieldVolumes():
418			f.volInput.Focus()
419		case f.focusedField == f.fieldUser():
420			f.userInput.Focus()
421		}
422	}
423	
424	func (f *LaunchForm) updateActiveInput(msg tea.Msg) (*LaunchForm, tea.Cmd) {
425		var cmd tea.Cmd
426		switch {
427		case f.focusedField == 0:
428			f.nameInput, cmd = f.nameInput.Update(msg)
429		case f.isPortField(f.focusedField):
430			portIdx := f.focusedField - f.firstPortField()
431			f.ports[portIdx].hostPortInput, cmd = f.ports[portIdx].hostPortInput.Update(msg)
432			f.revalidate()
433		case f.focusedField == f.fieldExtraPorts():
434			f.extraPortsInput, cmd = f.extraPortsInput.Update(msg)
435		case f.focusedField == f.fieldEntrypoint():
436			prev := f.entrypointInput.Value()
437			f.entrypointInput, cmd = f.entrypointInput.Update(msg)
438			if newVal := f.entrypointInput.Value(); newVal != prev {
439				verifyCmd := f.onEntrypointChanged(newVal)
440				cmd = tea.Batch(cmd, verifyCmd)
441			}
442		case f.focusedField == f.fieldEnv():
443			f.envInput, cmd = f.envInput.Update(msg)
444		case f.focusedField == f.fieldVolumes():
445			f.volInput, cmd = f.volInput.Update(msg)
446		case f.focusedField == f.fieldUser():
447			f.userInput, cmd = f.userInput.Update(msg)
448		}
449		return f, cmd
450	}
451	
452	// onEntrypointChanged applies auto-selection logic and triggers a verification check.
453	func (f *LaunchForm) onEntrypointChanged(newVal string) tea.Cmd {
454		f.lastEntrypoint = newVal
455	
456		if newVal == "" {
457			f.verify = verifyIdle
458			f.verifySeq++
459			return nil
460		}
461	
462		// Auto-select Interactive/TTY when the entrypoint looks like a shell
463		baseName := strings.ToLower(filepath.Base(newVal))
464		if commonShells[baseName] {
465			f.optionInteractiveTTY = true
466			f.optionDetach = false
467		}
468	
469		// Start debounced verification
470		f.verify = verifyChecking
471		f.verifySeq++
472		return verifyEntrypointCmd(f.verifySeq, f.image, newVal)
473	}
474	
475	// portKey is the validation key of the host port at index i.
476	func portKey(i int) string { return fmt.Sprintf("port:%d", i) }
477	
478	// normalizeHostPort trims s and returns the port it names without leading
479	// zeros ("0080" is "80"). Empty or blank is accepted and stays empty (the
480	// container port is used); anything else must be ASCII digits between 1 and
481	// 65535, so no sign and no "+80".
482	func normalizeHostPort(s string) (string, bool) {
483		s = strings.TrimSpace(s)
484		if s == "" {
485			return "", true
486		}
487		for _, r := range s {
488			if r < '0' || r > '9' {
489				return "", false
490			}
491		}
492		n, err := strconv.Atoi(s)
493		if err != nil || n < 1 || n > 65535 {
494			return "", false
495		}
496		return strconv.Itoa(n), true
497	}
498	
499	// validHostPort reports whether s is acceptable as a host port.
500	func validHostPort(s string) bool {
501		_, ok := normalizeHostPort(s)
502		return ok
503	}
504	
505	// validate returns the invalid host ports of the ticked EXPOSE ports, in
506	// display order. Additional ports and Environment stay free-form.
507	func (f *LaunchForm) validate() []sharedcomponents.FieldError {
508		var errs []sharedcomponents.FieldError
509		for i := range f.ports {
510			if f.ports[i].enabled && !validHostPort(f.ports[i].hostPortInput.Value()) {
511				errs = append(errs, sharedcomponents.FieldError{
512					Key:  portKey(i),
513					Text: "Host port for " + f.ports[i].containerPort + " must be a number between 1 and 65535",
514				})
515			}
516		}
517		return errs
518	}
519	
520	// revalidate refreshes the errors after a change; it says nothing until a
521	// submit has been refused.
522	func (f *LaunchForm) revalidate() {
523		f.validation.Revalidate(f.validate())
524		f.applyInvalid()
525	}
526	
527	// applyInvalid underlines the host ports that currently fail validation,
528	// restyling only those whose state changed.
529	func (f *LaunchForm) applyInvalid() {
530		for i := range f.ports {
531			f.marks.Sync(portKey(i), &f.ports[i].hostPortInput, f.validation.Invalid(portKey(i)))
532		}
533	}
534	
535	// ValidationStatus is the footer line for the current errors, derived on every
536	// call; the zero Status means none.
537	func (f *LaunchForm) ValidationStatus() sharedcomponents.Status { return f.validation.Status() }
538	
539	func (f *LaunchForm) submit() (*LaunchForm, tea.Cmd) {
540		ok := f.validation.Submit(f.validate())
541		f.applyInvalid()
542		if !ok {
543			return f, nil
544		}
545		opts := docker.ContainerLaunchOptions{
546			Image:       f.image,
547			Name:        strings.TrimSpace(f.nameInput.Value()),
548			Entrypoint:  strings.TrimSpace(f.entrypointInput.Value()),
549			User:        strings.TrimSpace(f.userInput.Value()),
550			Detach:      f.optionDetach,
551			Remove:      f.optionRemove,
552			Interactive: f.optionInteractiveTTY,
553			TTY:         f.optionInteractiveTTY,
554		}
555		// Collect enabled image ports with their (possibly customised) host mapping
556		for i := range f.ports {
557			if f.ports[i].enabled {
558				opts.Ports = append(opts.Ports, f.ports[i].mappingArg())
559			}
560		}
561		// Extra port mappings: comma-separated host:container pairs
562		for p := range strings.SplitSeq(f.extraPortsInput.Value(), ",") {
563			if p = strings.TrimSpace(p); p != "" {
564				opts.Ports = append(opts.Ports, p)
565			}
566		}
567		// Env vars: comma-separated KEY=VALUE entries
568		for e := range strings.SplitSeq(f.envInput.Value(), ",") {
569			if e = strings.TrimSpace(e); e != "" {
570				opts.Env = append(opts.Env, e)
571			}
572		}
573		// Volume mounts: comma-separated vol:/path entries
574		for v := range strings.SplitSeq(f.volInput.Value(), ",") {
575			if v = strings.TrimSpace(v); v != "" {
576				opts.Volumes = append(opts.Volumes, v)
577			}
578		}
579		if len(f.networks) > 0 {
580			opts.Network = f.networks[f.networkIdx]
581		}
582		return f, func() tea.Msg { return LaunchFormSubmitMsg{Opts: opts} }
583	}
584

