package ociresources

import (
	"fmt"
	"path/filepath"
	"strconv"
	"strings"

	"charm.land/bubbles/v2/textinput"
	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/docker"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// LaunchFormSubmitMsg is sent when the launch form is submitted
type LaunchFormSubmitMsg struct {
	Opts docker.ContainerLaunchOptions
}

// LaunchFormCancelMsg is sent when the launch form is cancelled
type LaunchFormCancelMsg struct{}

// EntrypointVerifyFinishedMsg is sent when the background entrypoint verification completes.
// Seq guards against stale results from previous verification runs.
type EntrypointVerifyFinishedMsg struct {
	Seq int
	OK  bool
}

// portEntry represents a port declared by EXPOSE in the image, with an editable host mapping.
type portEntry struct {
	containerPort string          // e.g. "80/tcp" — fixed, from image EXPOSE
	hostPortInput textinput.Model // editable host port number, defaults to the container port number
	enabled       bool
}

// containerPortNum returns the numeric part of containerPort (strips "/protocol" suffix).
func (p *portEntry) containerPortNum() string {
	if idx := strings.Index(p.containerPort, "/"); idx > 0 {
		return p.containerPort[:idx]
	}
	return p.containerPort
}

// mappingArg returns the "-p host:container" argument value for docker run.
// Falls back to the container port number when the host input is empty.
func (p *portEntry) mappingArg() string {
	host, ok := normalizeHostPort(p.hostPortInput.Value())
	if !ok {
		host = strings.TrimSpace(p.hostPortInput.Value()) // refused by validate() before it gets here
	}
	container := p.containerPortNum()
	if host == "" {
		host = container
	}
	return host + ":" + container
}

// verifyState represents the entrypoint verification status
type verifyState int

const (
	verifyIdle     verifyState = iota // no entrypoint typed
	verifyChecking                    // docker check in progress
	verifyOK                          // binary found in image
	verifyWarning                     // binary not found
)

// commonShells lists base names that trigger auto-selection of Interactive/TTY mode
var commonShells = map[string]bool{
	"sh": true, "bash": true, "zsh": true, "fish": true,
	"dash": true, "ksh": true, "csh": true, "tcsh": true,
	"ash": true, "python": true, "python3": true, "busybox": true,
}

// LaunchForm is a viewport form for launching a container from an image
type LaunchForm struct {
	image                string
	nameInput            textinput.Model
	ports                []portEntry     // one row per image EXPOSE port
	extraPortsInput      textinput.Model // free-form extra port mappings (comma-separated host:container)
	entrypointInput      textinput.Model
	envInput             textinput.Model
	volInput             textinput.Model
	userInput            textinput.Model // --user UID:GID or username (optional)
	networks             []string        // available Docker network names
	networkIdx           int             // index into networks
	optionRemove         bool            // --rm: remove container on exit
	optionDetach         bool            // -d: run in background
	optionInteractiveTTY bool            // -it: interactive + TTY
	verify               verifyState
	verifySeq            int    // incremented on each new verification to discard stale results
	lastEntrypoint       string // tracks previous entrypoint value for change detection
	focusedField         int
	validation           sharedcomponents.Validation // host port errors, live after a refused submit (DEVDESK-292)
	marks                sharedcomponents.InvalidMarks
	width                int // viewport content width for two-column layout
}

// NewLaunchForm creates a launch form pre-filled with exposed ports and available networks.
// exposedPorts is a slice of "port/protocol" strings, e.g. ["80/tcp", "443/tcp"].
func NewLaunchForm(imageName string, exposedPorts []string, networks []docker.Network, width int) *LaunchForm {
	newInput := func(placeholder string) textinput.Model {
		ti := textinput.New()
		ti.CharLimit = 512
		theme.StyleTextInput(&ti)
		ti.Placeholder = placeholder
		return ti
	}

	nameInput := newInput("container-name (optional)")
	entrypointInput := newInput("/bin/sh (optional override)")
	envInput := newInput("APP_PORT=8080")
	volInput := newInput("myvolume:/app/data")
	userInput := newInput("1000:1000 or username (optional)")
	extraPortsInput := newInput("8080:8080, 9090:9090")

	// Build port entries from image EXPOSE specs — all enabled by default
	var ports []portEntry
	for _, spec := range exposedPorts {
		// spec = "80/tcp" or bare "80"
		portNum := spec
		if idx := strings.Index(spec, "/"); idx > 0 {
			portNum = spec[:idx]
		}
		hi := textinput.New()
		hi.CharLimit = 10
		hi.SetWidth(6)
		theme.StyleTextInput(&hi)
		hi.SetValue(portNum)
		ports = append(ports, portEntry{
			containerPort: spec,
			hostPortInput: hi,
			enabled:       true,
		})
	}

	// Build network list, always include bridge as fallback
	var netNames []string
	seen := map[string]bool{}
	for _, n := range networks {
		if !seen[n.Name] {
			netNames = append(netNames, n.Name)
			seen[n.Name] = true
		}
	}
	if len(netNames) == 0 {
		netNames = []string{"bridge"}
	}

	nameInput.Focus()

	f := &LaunchForm{
		image:           imageName,
		nameInput:       nameInput,
		ports:           ports,
		extraPortsInput: extraPortsInput,
		entrypointInput: entrypointInput,
		envInput:        envInput,
		volInput:        volInput,
		userInput:       userInput,
		networks:        netNames,
		optionDetach:    true, // default: run in background
		width:           width,
	}
	f.resizeInputs()
	return f
}

// ToCacheEntry extracts the current form field values into a LaunchOptionsEntry for caching.
// The container name is intentionally excluded (must be unique per container).
func (f *LaunchForm) ToCacheEntry() cache.LaunchOptionsEntry {
	portMappings := make(map[string]cache.PortMappingEntry, len(f.ports))
	for _, p := range f.ports {
		portMappings[p.containerPort] = cache.PortMappingEntry{
			HostPort: p.hostPortInput.Value(),
			Enabled:  p.enabled,
		}
	}
	network := ""
	if len(f.networks) > 0 {
		network = f.networks[f.networkIdx]
	}
	return cache.LaunchOptionsEntry{
		Entrypoint:   f.entrypointInput.Value(),
		ExtraPorts:   f.extraPortsInput.Value(),
		Env:          f.envInput.Value(),
		Volumes:      f.volInput.Value(),
		User:         f.userInput.Value(),
		Network:      network,
		Remove:       f.optionRemove,
		Detach:       f.optionDetach,
		Interactive:  f.optionInteractiveTTY,
		PortMappings: portMappings,
	}
}

// ApplyCached pre-fills the form fields from a cached launch options entry.
func (f *LaunchForm) ApplyCached(entry cache.LaunchOptionsEntry) {
	f.entrypointInput.SetValue(entry.Entrypoint)
	f.lastEntrypoint = entry.Entrypoint
	f.extraPortsInput.SetValue(entry.ExtraPorts)
	f.envInput.SetValue(entry.Env)
	f.volInput.SetValue(entry.Volumes)
	f.userInput.SetValue(entry.User)
	f.optionRemove = entry.Remove
	f.optionDetach = entry.Detach
	f.optionInteractiveTTY = entry.Interactive

	// Apply cached network selection by name
	if entry.Network != "" {
		for i, n := range f.networks {
			if n == entry.Network {
				f.networkIdx = i
				break
			}
		}
	}

	// Apply cached port mappings by container port key; unmatched ports keep defaults
	for i := range f.ports {
		if pm, ok := entry.PortMappings[f.ports[i].containerPort]; ok {
			f.ports[i].hostPortInput.SetValue(pm.HostPort)
			f.ports[i].hostPortInput.CursorEnd() // SetValue while blurred leaves a stale cursor
			f.ports[i].enabled = pm.Enabled
		}
	}
}

// GetTitle returns the form title for use in the viewport breadcrumb
func (f *LaunchForm) GetTitle() string { return "Launch Container" }

// SetWidth updates the form width for responsive two-column rendering
func (f *LaunchForm) SetWidth(w int) {
	f.width = w
	f.resizeInputs()
}

func (f *LaunchForm) resizeInputs() {
	// In two-column mode the left column is 55% of width; inputs sit below their label with 2-char indent.
	inputWidth := f.width - 4
	if f.width >= 100 {
		inputWidth = f.width*55/100 - 4
	}
	inputWidth = max(inputWidth, 20)
	f.nameInput.SetWidth(inputWidth)
	f.entrypointInput.SetWidth(inputWidth)
	f.envInput.SetWidth(inputWidth)
	f.volInput.SetWidth(inputWidth)
	f.userInput.SetWidth(inputWidth)
	f.extraPortsInput.SetWidth(inputWidth)
}

// Field indices follow the visual render order:
// 0:name  1:entrypoint  2:env  3:volumes  4:user  5:network  6..6+n-1:ports  6+n:extraPorts  6+n+1..+3:options  6+n+4:submit
const firstPortFieldOffset = 6

func (f *LaunchForm) fieldEntrypoint() int        { return 1 }
func (f *LaunchForm) fieldEnv() int               { return 2 }
func (f *LaunchForm) fieldVolumes() int           { return 3 }
func (f *LaunchForm) fieldUser() int              { return 4 }
func (f *LaunchForm) fieldNetwork() int           { return 5 }
func (f *LaunchForm) firstPortField() int         { return firstPortFieldOffset }
func (f *LaunchForm) fieldExtraPorts() int        { return firstPortFieldOffset + len(f.ports) }
func (f *LaunchForm) fieldOptionRemove() int      { return firstPortFieldOffset + len(f.ports) + 1 }
func (f *LaunchForm) fieldOptionDetach() int      { return firstPortFieldOffset + len(f.ports) + 2 }
func (f *LaunchForm) fieldOptionInteractive() int { return firstPortFieldOffset + len(f.ports) + 3 }
func (f *LaunchForm) fieldSubmit() int            { return firstPortFieldOffset + len(f.ports) + 4 }

// isPortField returns true if the given index corresponds to a port entry row
func (f *LaunchForm) isPortField(idx int) bool {
	return idx >= f.firstPortField() && idx < f.firstPortField()+len(f.ports)
}

// Update handles messages for the launch form
func (f *LaunchForm) Update(msg tea.Msg) (*LaunchForm, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyPressMsg:
		return f.handleKeyMsg(msg)
	case EntrypointVerifyFinishedMsg:
		return f.handleVerifyFinished(msg)
	}
	return f.updateActiveInput(msg)
}

func (f *LaunchForm) handleKeyMsg(msg tea.KeyPressMsg) (*LaunchForm, tea.Cmd) {
	maxField := f.fieldSubmit()

	switch msg.String() {
	case "ctrl+y":
		return f, copyToClipboardCmd(f.buildCommandString())

	case "esc":
		return f, func() tea.Msg { return LaunchFormCancelMsg{} }

	case "down":
		f.focusedField = (f.focusedField + 1) % (maxField + 1)
		f.updateFocus()
		return f, nil

	case "up":
		f.focusedField = (f.focusedField - 1 + maxField + 1) % (maxField + 1)
		f.updateFocus()
		return f, nil

	case "left":
		if f.focusedField == f.fieldNetwork() && len(f.networks) > 0 {
			f.networkIdx = (f.networkIdx - 1 + len(f.networks)) % len(f.networks)
			return f, nil
		}
	case "right":
		if f.focusedField == f.fieldNetwork() && len(f.networks) > 0 {
			f.networkIdx = (f.networkIdx + 1) % len(f.networks)
			return f, nil
		}

	case keymap.Space:
		// Space toggles checkboxes (Rule 135): port fields and option checkboxes
		if f.isPortField(f.focusedField) {
			f.ports[f.focusedField-f.firstPortField()].enabled = !f.ports[f.focusedField-f.firstPortField()].enabled
			f.revalidate()
			return f, nil
		}
		if f.isOptionField(f.focusedField) {
			return f.handleSpaceKey()
		}
		// A text field takes the space as a character (DEVDESK-266).
		return f.updateActiveInput(msg)

	case "enter":
		// Enter advances to next field or submits; never toggles (Rule 135)
		return f.handleEnterKey()
	}

	return f.updateActiveInput(msg)
}

// handleEnterKey processes Enter: advances to next field or submits (Rule 135 — never toggles).
func (f *LaunchForm) handleEnterKey() (*LaunchForm, tea.Cmd) {
	maxField := f.fieldSubmit()
	if f.focusedField == maxField {
		return f.submit()
	}
	f.focusedField = (f.focusedField + 1) % (maxField + 1)
	f.updateFocus()
	return f, nil
}

// isOptionField reports whether a field is one of the option checkboxes.
func (f *LaunchForm) isOptionField(field int) bool {
	return field == f.fieldOptionRemove() || field == f.fieldOptionDetach() ||
		field == f.fieldOptionInteractive()
}

// handleSpaceKey processes Space: toggles option checkboxes (Rule 135).
func (f *LaunchForm) handleSpaceKey() (*LaunchForm, tea.Cmd) {
	if f.focusedField == f.fieldOptionRemove() {
		f.optionRemove = !f.optionRemove
		return f, nil
	}
	if f.focusedField == f.fieldOptionDetach() {
		f.optionDetach = !f.optionDetach
		if f.optionDetach {
			f.optionInteractiveTTY = false
		}
		return f, nil
	}
	if f.focusedField == f.fieldOptionInteractive() {
		f.optionInteractiveTTY = !f.optionInteractiveTTY
		if f.optionInteractiveTTY {
			f.optionDetach = false
		}
		return f, nil
	}
	return f, nil
}

// handleVerifyFinished updates the verify state, discarding stale results
func (f *LaunchForm) handleVerifyFinished(msg EntrypointVerifyFinishedMsg) (*LaunchForm, tea.Cmd) {
	if msg.Seq != f.verifySeq {
		return f, nil // stale result from a previous entrypoint value
	}
	if msg.OK {
		f.verify = verifyOK
	} else {
		f.verify = verifyWarning
	}
	return f, nil
}

func (f *LaunchForm) updateFocus() {
	f.nameInput.Blur()
	f.extraPortsInput.Blur()
	f.entrypointInput.Blur()
	f.envInput.Blur()
	f.volInput.Blur()
	f.userInput.Blur()
	for i := range f.ports {
		f.ports[i].hostPortInput.Blur()
	}
	switch {
	case f.focusedField == 0:
		f.nameInput.Focus()
	case f.isPortField(f.focusedField):
		in := &f.ports[f.focusedField-f.firstPortField()].hostPortInput
		in.Focus()
	case f.focusedField == f.fieldExtraPorts():
		f.extraPortsInput.Focus()
	case f.focusedField == f.fieldEntrypoint():
		f.entrypointInput.Focus()
	case f.focusedField == f.fieldEnv():
		f.envInput.Focus()
	case f.focusedField == f.fieldVolumes():
		f.volInput.Focus()
	case f.focusedField == f.fieldUser():
		f.userInput.Focus()
	}
}

func (f *LaunchForm) updateActiveInput(msg tea.Msg) (*LaunchForm, tea.Cmd) {
	var cmd tea.Cmd
	switch {
	case f.focusedField == 0:
		f.nameInput, cmd = f.nameInput.Update(msg)
	case f.isPortField(f.focusedField):
		portIdx := f.focusedField - f.firstPortField()
		f.ports[portIdx].hostPortInput, cmd = f.ports[portIdx].hostPortInput.Update(msg)
		f.revalidate()
	case f.focusedField == f.fieldExtraPorts():
		f.extraPortsInput, cmd = f.extraPortsInput.Update(msg)
	case f.focusedField == f.fieldEntrypoint():
		prev := f.entrypointInput.Value()
		f.entrypointInput, cmd = f.entrypointInput.Update(msg)
		if newVal := f.entrypointInput.Value(); newVal != prev {
			verifyCmd := f.onEntrypointChanged(newVal)
			cmd = tea.Batch(cmd, verifyCmd)
		}
	case f.focusedField == f.fieldEnv():
		f.envInput, cmd = f.envInput.Update(msg)
	case f.focusedField == f.fieldVolumes():
		f.volInput, cmd = f.volInput.Update(msg)
	case f.focusedField == f.fieldUser():
		f.userInput, cmd = f.userInput.Update(msg)
	}
	return f, cmd
}

// onEntrypointChanged applies auto-selection logic and triggers a verification check.
func (f *LaunchForm) onEntrypointChanged(newVal string) tea.Cmd {
	f.lastEntrypoint = newVal

	if newVal == "" {
		f.verify = verifyIdle
		f.verifySeq++
		return nil
	}

	// Auto-select Interactive/TTY when the entrypoint looks like a shell
	baseName := strings.ToLower(filepath.Base(newVal))
	if commonShells[baseName] {
		f.optionInteractiveTTY = true
		f.optionDetach = false
	}

	// Start debounced verification
	f.verify = verifyChecking
	f.verifySeq++
	return verifyEntrypointCmd(f.verifySeq, f.image, newVal)
}

// portKey is the validation key of the host port at index i.
func portKey(i int) string { return fmt.Sprintf("port:%d", i) }

// normalizeHostPort trims s and returns the port it names without leading
// zeros ("0080" is "80"). Empty or blank is accepted and stays empty (the
// container port is used); anything else must be ASCII digits between 1 and
// 65535, so no sign and no "+80".
func normalizeHostPort(s string) (string, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return "", true
	}
	for _, r := range s {
		if r < '0' || r > '9' {
			return "", false
		}
	}
	n, err := strconv.Atoi(s)
	if err != nil || n < 1 || n > 65535 {
		return "", false
	}
	return strconv.Itoa(n), true
}

// validHostPort reports whether s is acceptable as a host port.
func validHostPort(s string) bool {
	_, ok := normalizeHostPort(s)
	return ok
}

// validate returns the invalid host ports of the ticked EXPOSE ports, in
// display order. Additional ports and Environment stay free-form.
func (f *LaunchForm) validate() []sharedcomponents.FieldError {
	var errs []sharedcomponents.FieldError
	for i := range f.ports {
		if f.ports[i].enabled && !validHostPort(f.ports[i].hostPortInput.Value()) {
			errs = append(errs, sharedcomponents.FieldError{
				Key:  portKey(i),
				Text: "Host port for " + f.ports[i].containerPort + " must be a number between 1 and 65535",
			})
		}
	}
	return errs
}

// revalidate refreshes the errors after a change; it says nothing until a
// submit has been refused.
func (f *LaunchForm) revalidate() {
	f.validation.Revalidate(f.validate())
	f.applyInvalid()
}

// applyInvalid underlines the host ports that currently fail validation,
// restyling only those whose state changed.
func (f *LaunchForm) applyInvalid() {
	for i := range f.ports {
		f.marks.Sync(portKey(i), &f.ports[i].hostPortInput, f.validation.Invalid(portKey(i)))
	}
}

// ValidationStatus is the footer line for the current errors, derived on every
// call; the zero Status means none.
func (f *LaunchForm) ValidationStatus() sharedcomponents.Status { return f.validation.Status() }

func (f *LaunchForm) submit() (*LaunchForm, tea.Cmd) {
	ok := f.validation.Submit(f.validate())
	f.applyInvalid()
	if !ok {
		return f, nil
	}
	opts := docker.ContainerLaunchOptions{
		Image:       f.image,
		Name:        strings.TrimSpace(f.nameInput.Value()),
		Entrypoint:  strings.TrimSpace(f.entrypointInput.Value()),
		User:        strings.TrimSpace(f.userInput.Value()),
		Detach:      f.optionDetach,
		Remove:      f.optionRemove,
		Interactive: f.optionInteractiveTTY,
		TTY:         f.optionInteractiveTTY,
	}
	// Collect enabled image ports with their (possibly customised) host mapping
	for i := range f.ports {
		if f.ports[i].enabled {
			opts.Ports = append(opts.Ports, f.ports[i].mappingArg())
		}
	}
	// Extra port mappings: comma-separated host:container pairs
	for p := range strings.SplitSeq(f.extraPortsInput.Value(), ",") {
		if p = strings.TrimSpace(p); p != "" {
			opts.Ports = append(opts.Ports, p)
		}
	}
	// Env vars: comma-separated KEY=VALUE entries
	for e := range strings.SplitSeq(f.envInput.Value(), ",") {
		if e = strings.TrimSpace(e); e != "" {
			opts.Env = append(opts.Env, e)
		}
	}
	// Volume mounts: comma-separated vol:/path entries
	for v := range strings.SplitSeq(f.volInput.Value(), ",") {
		if v = strings.TrimSpace(v); v != "" {
			opts.Volumes = append(opts.Volumes, v)
		}
	}
	if len(f.networks) > 0 {
		opts.Network = f.networks[f.networkIdx]
	}
	return f, func() tea.Msg { return LaunchFormSubmitMsg{Opts: opts} }
}

package netdiag

import (
	"log"

	"charm.land/bubbles/v2/textinput"
	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/forward"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/shared"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/keymap"
)

// Init implements tea.Model
func (m *Model) Init() tea.Cmd {
	// The router runs Init on every entry. A source listing that came back while
	// another view was on screen went to that view, so a selector left open
	// would wait for it for good; it closes here instead.
	m.pathModel.closePicker()
	return tea.Batch(
		textinput.Blink,
		m.portsModel.initPorts(),
		m.interfacesModel.initInterfaces(),
		// The forwards live on the router, which broadcasts when they change.
		// A view built after the last change was not there for it, so it asks
		// once on the way in — the role sendJobsTo plays for the job registry.
		forward.Refresh,
	)
}

// Running reports whether a diagnostic is walking its stages now, which is what
// the router asks before it would rebuild the view: dropping it mid-run would
// discard the run without a word.
//
// A path trace counts too, even from another tab: it goes on there.
func (m *Model) Running() bool { return m.state == StateRunning || m.pathModel.running() }

// InEditMode implements FormView — true when a text input is active, so the
// router hands the key to the field rather than opening the command line.
func (m *Model) InEditMode() bool {
	switch m.activeTab {
	case tabPorts:
		return m.portsModel.InEditMode()
	case tabInterfaces:
		// The interfaces table has a search box now, where the Topology tab it
		// replaced had no input at all. Returning false here would let a ":"
		// typed into the query open the command line instead (Rule 111).
		return m.interfacesModel.InEditMode()
	case tabForward:
		return m.forwardModel.InEditMode()
	case tabPath:
		return m.pathModel.InEditMode()
	}
	if m.filterBar.InEditMode() {
		return true
	}
	if m.state == StateInput {
		return m.focusedField == fieldTarget || m.focusedField == fieldPort || m.focusedField == fieldDNSServer
	}
	return false
}

// Update implements tea.Model
func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.resizeInputs()
		m.filterBar.Resize(msg.Width)
		m.rebuildChecksTable()
		m.resizeDetailsViewport()
		m.portsModel.resize(msg.Width, msg.Height)
		m.interfacesModel.resize(msg.Width, msg.Height)
		m.forwardModel.resize(msg.Width, msg.Height)
		m.pathModel.resize(msg.Width, msg.Height)
		return m, nil

	// The router's animation frame: the blink phase of the Ports dot and of the
	// two footers that show the shared activity dot, whichever tab is on screen
	// so a tab never comes back with a frozen phase.
	case jobs.FrameMsg:
		m.portsModel.table.SetBlinkPhase(msg.Blink)
		m.footer.SetBlinkPhase(msg.Blink)
		m.interfacesModel.footer.SetBlinkPhase(msg.Blink)
		m.pathModel.footer.SetBlinkPhase(msg.Blink)
		return m, nil

	case stageDoneMsg:
		return m.handleStageDone(msg)

	// Ports sub-model messages.
	case portsTickMsg, portsDataMsg, portsKillResultMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// The terminal focus reaches the ports poll on every tab: its tick runs
	// whichever tab shows.
	case shared.TerminalFocusMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// Two tabs now ask before they act — Ports before a kill (§3.26), Forward
	// before dropping the connections a redirection is carrying — so the answer
	// goes to the tab that asked rather than to Ports unconditionally, which
	// would have confirmed a kill from the Forward tab's modal.
	case components.ConfirmModalYesMsg, components.ConfirmModalNoMsg:
		return m.routeConfirm(msg)

	// Forward sub-model messages. ChangedMsg is the router's broadcast, and it
	// reaches this view wherever it stands, on screen or not.
	case forward.ChangedMsg, forwardTickMsg, ForwardFormSubmitMsg, ForwardFormCancelMsg:
		var cmd tea.Cmd
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd

	// Path sub-model messages: a trace goes on, and its hops keep arriving,
	// whichever tab is on screen.
	case pathResolvedMsg, pathHopMsg, pathDoneMsg, pathSourcesMsg:
		var cmd tea.Cmd
		m.pathModel, cmd = m.pathModel.update(msg)
		return m, cmd

	// Topology sub-model messages
	case ifaceDataMsg:
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd

	case tea.KeyPressMsg:
		return m.handleKey(msg)

	case tea.PasteMsg:
		return m.handlePaste(msg)
	}

	// Each tab holds its own footer, so an expiry has to be offered to all
	// five: the timer fires wherever the user has since navigated. The Path tab
	// also takes the cursor blink of its field.
	m.footer.Handle(msg)
	m.portsModel.footer.Handle(msg)
	m.interfacesModel.footer.Handle(msg)
	m.forwardModel.footer.Handle(msg)
	var cmd tea.Cmd
	m.pathModel, cmd = m.pathModel.update(msg)
	return m, cmd
}

// routeConfirm hands a confirmation answer to the tab that put the modal up.
func (m *Model) routeConfirm(msg tea.Msg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	if m.activeTab == tabForward {
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd
	}
	m.portsModel, cmd = m.portsModel.update(msg)
	return m, cmd
}

// handleStageDone records one stage's answers and starts the next.
func (m *Model) handleStageDone(msg stageDoneMsg) (*Model, tea.Cmd) {
	if msg.gen != m.runGen {
		return m, nil // a superseded run
	}
	m.results = msg.results
	m.rebuildChecksTable()

	steps := netcheck.Steps()
	if msg.next >= len(steps) {
		m.state = StateResults
		m.verdict = netcheck.Summarize(m.results.All())
		log.Printf("INFO [netdiag] run finished: verdict=%s over %d checks",
			m.verdict, len(m.results.All()))
		return m, nil
	}

	m.runStep = msg.next
	m.runStage = steps[msg.next]

	tg, err := m.buildTarget()
	if err != nil {
		// The form has not changed since the run started, so this cannot
		// normally fail. Reporting it beats continuing with a target nobody
		// can name.
		log.Printf("ERROR [netdiag] target became invalid mid-run: %v", err)
		m.state = StateResults
		return m, m.footer.Error("Run stopped — the target is no longer valid")
	}
	return m, runStageCmd(m.runGen, tg, m.checkSettings(), msg.next, m.results)
}

// handlePaste gives pasted text to the field that has the keyboard on the tab on
// screen. It never reaches the key handlers, so no action fires (Rule 111).
func (m *Model) handlePaste(msg tea.PasteMsg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	switch m.activeTab {
	case tabPorts:
		m.portsModel, cmd = m.portsModel.update(msg)
	case tabInterfaces:
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
	case tabForward:
		m.forwardModel, cmd = m.forwardModel.update(msg)
	case tabPath:
		m.pathModel, cmd = m.pathModel.update(msg)
	default:
		switch {
		case m.filterBar.InEditMode():
			m.filterBar, cmd = m.filterBar.Update(msg)
			m.rebuildChecksTable()
		case m.state == StateInput:
			return m.updateActiveInput(msg)
		}
	}
	return m, cmd
}

func (m *Model) handleKey(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	// A filter bar in edit mode claims every key before anything else, or a
	// query cannot contain the letters the view binds.
	if m.activeTab == tabDiagnostics && m.filterBar.InEditMode() {
		var cmd tea.Cmd
		m.filterBar, cmd = m.filterBar.Update(msg)
		m.rebuildChecksTable()
		return m, cmd
	}

	// An open selector holds every key, tab included: it is a mode.
	if m.activeTab == tabPath && m.pathModel.pickerOpen() {
		var cmd tea.Cmd
		m.pathModel, cmd = m.pathModel.update(msg)
		return m, cmd
	}

	// Tab / Shift+Tab cycles between the tabs (Rule 135)
	switch msg.String() {
	case "tab":
		m.activeTab = (m.activeTab + 1) % tabCount
		return m, nil
	case "shift+tab":
		m.activeTab = (m.activeTab + tabCount - 1) % tabCount
		return m, nil
	}

	// Route to active tab
	if m.activeTab == tabPorts {
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabInterfaces {
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabForward {
		var cmd tea.Cmd
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabPath {
		var cmd tea.Cmd
		m.pathModel, cmd = m.pathModel.update(msg)
		return m, cmd
	}

	switch m.state {
	case StateInput:
		return m.handleKeyInput(msg)
	case StateRunning:
		return m.handleKeyRunning(msg)
	case StateResults:
		return m.handleKeyResults(msg)
	case StateDetails:
		return m.handleKeyDetails(msg)
	}
	return m, nil
}

// handleKeyRunning cancels the run. The stage in flight is awaited rather than
// interrupted — it is a network read that will time out on its own — and its
// result is discarded by the generation counter.
func (m *Model) handleKeyRunning(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	if msg.String() != "esc" {
		return m, nil
	}
	m.runGen++
	m.state = StateResults
	m.verdict = netcheck.Summarize(m.results.All())
	m.rebuildChecksTable()
	return m, m.footer.Warn("Run cancelled — showing what completed")
}

func (m *Model) handleKeyInput(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	switch msg.String() {
	case "down":
		m.moveFocus(1)
		return m, nil
	case "up":
		m.moveFocus(-1)
		return m, nil
	case "enter":
		// enter runs the checks from anywhere in the form, so the user need
		// not walk to the button first; only the Trace Path button means
		// something else.
		if m.focusedField == fieldTraceButton {
			return m.traceFromForm()
		}
		return m.StartRun()
	case "esc":
		return m, nil
	}
	return m.updateActiveInput(msg)
}

func (m *Model) moveFocus(delta int) {
	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Blur()
	case fieldPort:
		m.portInput.Blur()
	case fieldDNSServer:
		m.dnsServerInput.Blur()
	}

	m.focusedField = (m.focusedField + delta + fieldCount) % fieldCount

	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Focus()
	case fieldPort:
		m.portInput.Focus()
	case fieldDNSServer:
		m.dnsServerInput.Focus()
	}
}

func (m *Model) updateActiveInput(msg tea.Msg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	switch m.focusedField {
	case fieldTarget:
		m.targetInput, cmd = m.targetInput.Update(msg)
	case fieldPort:
		m.portInput, cmd = m.portInput.Update(msg)
	case fieldDNSServer:
		m.dnsServerInput, cmd = m.dnsServerInput.Update(msg)
	}
	return m, cmd
}

func (m *Model) handleKeyResults(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	switch msg.String() {
	case "enter":
		return m.openDetails()
	case "esc":
		// No origin view means netdiag was opened directly (the command
		// line), so esc stays inside it and resets to the form, as it
		// always has. An origin means it was opened prefilled from
		// elsewhere (status's H, §3.66), and esc returns there instead.
		if m.OriginView == "" {
			return m.resetToForm()
		}
		origin := m.OriginView
		return m, func() tea.Msg { return BackToOriginMsg{Origin: origin} }
	case "ctrl+r":
		return m.StartRun()
	case "/":
		return m, m.filterBar.ActivateSearch()
	case "p":
		m.filterBar.SetTokenActive(problemsToken, !m.filterBar.IsTokenActive(problemsToken))
		m.rebuildChecksTable()
		return m, nil
	case keymap.Diagnose:
		return m.tracePathFromRoute()
	case keymap.New:
		// Always resets to the form, regardless of OriginView — the one way
		// to run a wholly new diagnostic without first leaving to wherever
		// this run was opened from. Found missing the day §3.66 shipped H:
		// esc alone left no way back to the form once an origin was set, and
		// re-entering netdiag through the command line landed on the same
		// frozen results with the same problem, since the cached view (and
		// its OriginView) is reused rather than rebuilt.
		return m.resetToForm()
	}
	return m, m.checksTable.Update(msg)
}

func (m *Model) handleKeyDetails(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.state = StateResults
		return m, nil
	case "up":
		m.detailsViewport.ScrollUp(1)
	case "down":
		m.detailsViewport.ScrollDown(1)
	case "pgup":
		m.detailsViewport.HalfPageUp()
	case "pgdown":
		m.detailsViewport.HalfPageDown()
	case "home":
		m.detailsViewport.GotoTop()
	case "end":
		m.detailsViewport.GotoBottom()
	}
	return m, nil
}

func (m *Model) openDetails() (*Model, tea.Cmd) {
	c, ok := m.checksTable.Selected()
	if !ok {
		return m, nil
	}
	m.selected = c
	m.state = StateDetails
	m.resizeDetailsViewport()
	m.detailsViewport.SetContent(m.renderDetailsContent(m.detailsViewport.Width()))
	m.detailsViewport.GotoTop()
	return m, nil
}

func (m *Model) resetToForm() (*Model, tea.Cmd) {
	m.state = StateInput
	m.focusedField = fieldTarget
	m.targetInput.Focus()
	m.results = netcheck.Results{}
	m.verdict = netcheck.Unknown
	m.filterBar.ClearSearch()
	m.filterBar.SetTokenActive(problemsToken, false)
	m.rebuildChecksTable()
	// Starting over severs the tie to wherever this run was opened from: the
	// next run is not "the monitor status sent here" anymore, so esc on its
	// results should not try to leave for a view this new target has nothing
	// to do with.
	m.OriginView = ""
	return m, nil
}

