34	// portEntry represents a port declared by EXPOSE in the image, with an editable host mapping.
35	type portEntry struct {
36		containerPort string          // e.g. "80/tcp" — fixed, from image EXPOSE
37		hostPortInput textinput.Model // editable host port number, defaults to the container port number
38		enabled       bool
39	}
40	
41	// containerPortNum returns the numeric part of containerPort (strips "/protocol" suffix).
42	func (p *portEntry) containerPortNum() string {
43		if idx := strings.Index(p.containerPort, "/"); idx > 0 {
44			return p.containerPort[:idx]
45		}
46		return p.containerPort
47	}
48	
49	// mappingArg returns the "-p host:container" argument value for docker run.
50	// Falls back to the container port number when the host input is empty.
51	func (p *portEntry) mappingArg() string {
52		host, ok := normalizeHostPort(p.hostPortInput.Value())
53		if !ok {
54			host = strings.TrimSpace(p.hostPortInput.Value()) // refused by validate() before it gets here
55		}
56		container := p.containerPortNum()
57		if host == "" {
58			host = container
59		}
60		return host + ":" + container
61	}
