104	// NewLaunchForm creates a launch form pre-filled with exposed ports and available networks.
105	// exposedPorts is a slice of "port/protocol" strings, e.g. ["80/tcp", "443/tcp"].
106	func NewLaunchForm(imageName string, exposedPorts []string, networks []docker.Network, width int) *LaunchForm {
107		newInput := func(placeholder string) textinput.Model {
108			ti := textinput.New()
109			ti.CharLimit = 512
110			theme.StyleTextInput(&ti)
111			ti.Placeholder = placeholder
112			return ti
113		}
114	
115		nameInput := newInput("container-name (optional)")
116		entrypointInput := newInput("/bin/sh (optional override)")
117		envInput := newInput("APP_PORT=8080")
118		volInput := newInput("myvolume:/app/data")
119		userInput := newInput("1000:1000 or username (optional)")
120		extraPortsInput := newInput("8080:8080, 9090:9090")
121	
122		// Build port entries from image EXPOSE specs — all enabled by default
123		var ports []portEntry
124		for _, spec := range exposedPorts {
125			// spec = "80/tcp" or bare "80"
126			portNum := spec
127			if idx := strings.Index(spec, "/"); idx > 0 {
128				portNum = spec[:idx]
129			}
130			hi := textinput.New()
131			hi.CharLimit = 10
132			hi.SetWidth(6)
133			theme.StyleTextInput(&hi)
134			hi.SetValue(portNum)
135			ports = append(ports, portEntry{
136				containerPort: spec,
137				hostPortInput: hi,
138				enabled:       true,
139			})
140		}
141	
142		// Build network list, always include bridge as fallback
143		var netNames []string
144		seen := map[string]bool{}
145		for _, n := range networks {
146			if !seen[n.Name] {
147				netNames = append(netNames, n.Name)
148				seen[n.Name] = true
149			}
150		}
151		if len(netNames) == 0 {
152			netNames = []string{"bridge"}
153		}
154	
155		nameInput.Focus()
156	
157		f := &LaunchForm{
158			image:           imageName,
159			nameInput:       nameInput,
160			ports:           ports,
161			extraPortsInput: extraPortsInput,
162			entrypointInput: entrypointInput,
163			envInput:        envInput,
164			volInput:        volInput,
165			userInput:       userInput,
166			networks:        netNames,
167			optionDetach:    true, // default: run in background
168			width:           width,
169		}
170		f.resizeInputs()
171		return f
172	}
