202	// ApplyCached pre-fills the form fields from a cached launch options entry.
203	func (f *LaunchForm) ApplyCached(entry cache.LaunchOptionsEntry) {
204		f.entrypointInput.SetValue(entry.Entrypoint)
205		f.lastEntrypoint = entry.Entrypoint
206		f.extraPortsInput.SetValue(entry.ExtraPorts)
207		f.envInput.SetValue(entry.Env)
208		f.volInput.SetValue(entry.Volumes)
209		f.userInput.SetValue(entry.User)
210		f.optionRemove = entry.Remove
211		f.optionDetach = entry.Detach
212		f.optionInteractiveTTY = entry.Interactive
213	
214		// Apply cached network selection by name
215		if entry.Network != "" {
216			for i, n := range f.networks {
217				if n == entry.Network {
218					f.networkIdx = i
219					break
220				}
221			}
222		}
223	
224		// Apply cached port mappings by container port key; unmatched ports keep defaults
225		for i := range f.ports {
226			if pm, ok := entry.PortMappings[f.ports[i].containerPort]; ok {
227				f.ports[i].hostPortInput.SetValue(pm.HostPort)
228				f.ports[i].hostPortInput.CursorEnd() // SetValue while blurred leaves a stale cursor
229				f.ports[i].enabled = pm.Enabled
230			}
231		}
232	}
