243	func (f *LaunchForm) resizeInputs() {
244		// In two-column mode the left column is 55% of width; inputs sit below their label with 2-char indent.
245		inputWidth := f.width - 4
246		if f.width >= 100 {
247			inputWidth = f.width*55/100 - 4
248		}
249		inputWidth = max(inputWidth, 20)
250		f.nameInput.SetWidth(inputWidth)
251		f.entrypointInput.SetWidth(inputWidth)
252		f.envInput.SetWidth(inputWidth)
253		f.volInput.SetWidth(inputWidth)
254		f.userInput.SetWidth(inputWidth)
255		f.extraPortsInput.SetWidth(inputWidth)
256	}
