279	// Update handles messages for the launch form
280	func (f *LaunchForm) Update(msg tea.Msg) (*LaunchForm, tea.Cmd) {
281		switch msg := msg.(type) {
282		case tea.KeyPressMsg:
283			return f.handleKeyMsg(msg)
284		case EntrypointVerifyFinishedMsg:
285			return f.handleVerifyFinished(msg)
286		}
287		return f.updateActiveInput(msg)
288	}
289	
290	func (f *LaunchForm) handleKeyMsg(msg tea.KeyPressMsg) (*LaunchForm, tea.Cmd) {
291		maxField := f.fieldSubmit()
292	
293		switch msg.String() {
294		case "ctrl+y":
295			return f, copyToClipboardCmd(f.buildCommandString())
296	
297		case "esc":
298			return f, func() tea.Msg { return LaunchFormCancelMsg{} }
299	
300		case "down":
301			f.focusedField = (f.focusedField + 1) % (maxField + 1)
302			f.updateFocus()
303			return f, nil
304	
305		case "up":
306			f.focusedField = (f.focusedField - 1 + maxField + 1) % (maxField + 1)
307			f.updateFocus()
308			return f, nil
309	
310		case "left":
311			if f.focusedField == f.fieldNetwork() && len(f.networks) > 0 {
312				f.networkIdx = (f.networkIdx - 1 + len(f.networks)) % len(f.networks)
313				return f, nil
314			}
315		case "right":
316			if f.focusedField == f.fieldNetwork() && len(f.networks) > 0 {
317				f.networkIdx = (f.networkIdx + 1) % len(f.networks)
318				return f, nil
319			}
320	
321		case keymap.Space:
322			// Space toggles checkboxes (Rule 135): port fields and option checkboxes
323			if f.isPortField(f.focusedField) {
324				f.ports[f.focusedField-f.firstPortField()].enabled = !f.ports[f.focusedField-f.firstPortField()].enabled
325				f.revalidate()
326				return f, nil
327			}
328			if f.isOptionField(f.focusedField) {
329				return f.handleSpaceKey()
330			}
331			// A text field takes the space as a character (DEVDESK-266).
332			return f.updateActiveInput(msg)
333	
334		case "enter":
335			// Enter advances to next field or submits; never toggles (Rule 135)
336			return f.handleEnterKey()
337		}
338	
339		return f.updateActiveInput(msg)
340	}
341	
342	// handleEnterKey processes Enter: advances to next field or submits (Rule 135 — never toggles).
343	func (f *LaunchForm) handleEnterKey() (*LaunchForm, tea.Cmd) {
344		maxField := f.fieldSubmit()
345		if f.focusedField == maxField {
346			return f.submit()
347		}
348		f.focusedField = (f.focusedField + 1) % (maxField + 1)
349		f.updateFocus()
350		return f, nil
351	}
352	
353	// isOptionField reports whether a field is one of the option checkboxes.
354	func (f *LaunchForm) isOptionField(field int) bool {
355		return field == f.fieldOptionRemove() || field == f.fieldOptionDetach() ||
356			field == f.fieldOptionInteractive()
357	}
358	
359	// handleSpaceKey processes Space: toggles option checkboxes (Rule 135).
360	func (f *LaunchForm) handleSpaceKey() (*LaunchForm, tea.Cmd) {
361		if f.focusedField == f.fieldOptionRemove() {
362			f.optionRemove = !f.optionRemove
363			return f, nil
364		}
365		if f.focusedField == f.fieldOptionDetach() {
366			f.optionDetach = !f.optionDetach
367			if f.optionDetach {
368				f.optionInteractiveTTY = false
369			}
370			return f, nil
371		}
372		if f.focusedField == f.fieldOptionInteractive() {
373			f.optionInteractiveTTY = !f.optionInteractiveTTY
374			if f.optionInteractiveTTY {
375				f.optionDetach = false
376			}
377			return f, nil
378		}
379		return f, nil
380	}
