382	// handleVerifyFinished updates the verify state, discarding stale results
383	func (f *LaunchForm) handleVerifyFinished(msg EntrypointVerifyFinishedMsg) (*LaunchForm, tea.Cmd) {
384		if msg.Seq != f.verifySeq {
385			return f, nil // stale result from a previous entrypoint value
386		}
387		if msg.OK {
388			f.verify = verifyOK
389		} else {
390			f.verify = verifyWarning
391		}
392		return f, nil
393	}
