452	// onEntrypointChanged applies auto-selection logic and triggers a verification check.
453	func (f *LaunchForm) onEntrypointChanged(newVal string) tea.Cmd {
454		f.lastEntrypoint = newVal
455	
456		if newVal == "" {
457			f.verify = verifyIdle
458			f.verifySeq++
459			return nil
460		}
461	
462		// Auto-select Interactive/TTY when the entrypoint looks like a shell
463		baseName := strings.ToLower(filepath.Base(newVal))
464		if commonShells[baseName] {
465			f.optionInteractiveTTY = true
466			f.optionDetach = false
467		}
468	
469		// Start debounced verification
470		f.verify = verifyChecking
471		f.verifySeq++
472		return verifyEntrypointCmd(f.verifySeq, f.image, newVal)
473	}
