475	// portKey is the validation key of the host port at index i.
476	func portKey(i int) string { return fmt.Sprintf("port:%d", i) }
477	
478	// normalizeHostPort trims s and returns the port it names without leading
479	// zeros ("0080" is "80"). Empty or blank is accepted and stays empty (the
480	// container port is used); anything else must be ASCII digits between 1 and
481	// 65535, so no sign and no "+80".
482	func normalizeHostPort(s string) (string, bool) {
483		s = strings.TrimSpace(s)
484		if s == "" {
485			return "", true
486		}
487		for _, r := range s {
488			if r < '0' || r > '9' {
489				return "", false
490			}
491		}
492		n, err := strconv.Atoi(s)
493		if err != nil || n < 1 || n > 65535 {
494			return "", false
495		}
496		return strconv.Itoa(n), true
497	}
498	
499	// validHostPort reports whether s is acceptable as a host port.
500	func validHostPort(s string) bool {
501		_, ok := normalizeHostPort(s)
502		return ok
503	}
504	
505	// validate returns the invalid host ports of the ticked EXPOSE ports, in
506	// display order. Additional ports and Environment stay free-form.
507	func (f *LaunchForm) validate() []sharedcomponents.FieldError {
508		var errs []sharedcomponents.FieldError
509		for i := range f.ports {
510			if f.ports[i].enabled && !validHostPort(f.ports[i].hostPortInput.Value()) {
511				errs = append(errs, sharedcomponents.FieldError{
512					Key:  portKey(i),
513					Text: "Host port for " + f.ports[i].containerPort + " must be a number between 1 and 65535",
514				})
515			}
516		}
517		return errs
518	}
519	
520	// revalidate refreshes the errors after a change; it says nothing until a
521	// submit has been refused.
522	func (f *LaunchForm) revalidate() {
523		f.validation.Revalidate(f.validate())
524		f.applyInvalid()
525	}
526	
527	// applyInvalid underlines the host ports that currently fail validation,
528	// restyling only those whose state changed.
529	func (f *LaunchForm) applyInvalid() {
530		for i := range f.ports {
531			f.marks.Sync(portKey(i), &f.ports[i].hostPortInput, f.validation.Invalid(portKey(i)))
532		}
533	}
534	
535	// ValidationStatus is the footer line for the current errors, derived on every
536	// call; the zero Status means none.
537	func (f *LaunchForm) ValidationStatus() sharedcomponents.Status { return f.validation.Status() }
538	
539	func (f *LaunchForm) submit() (*LaunchForm, tea.Cmd) {
540		ok := f.validation.Submit(f.validate())
541		f.applyInvalid()
542		if !ok {
543			return f, nil
544		}
545		opts := docker.ContainerLaunchOptions{
546			Image:       f.image,
547			Name:        strings.TrimSpace(f.nameInput.Value()),
548			Entrypoint:  strings.TrimSpace(f.entrypointInput.Value()),
549			User:        strings.TrimSpace(f.userInput.Value()),
550			Detach:      f.optionDetach,
551			Remove:      f.optionRemove,
552			Interactive: f.optionInteractiveTTY,
553			TTY:         f.optionInteractiveTTY,
554		}
555		// Collect enabled image ports with their (possibly customised) host mapping
556		for i := range f.ports {
557			if f.ports[i].enabled {
558				opts.Ports = append(opts.Ports, f.ports[i].mappingArg())
559			}
560		}
561		// Extra port mappings: comma-separated host:container pairs
562		for p := range strings.SplitSeq(f.extraPortsInput.Value(), ",") {
563			if p = strings.TrimSpace(p); p != "" {
564				opts.Ports = append(opts.Ports, p)
565			}
566		}
567		// Env vars: comma-separated KEY=VALUE entries
568		for e := range strings.SplitSeq(f.envInput.Value(), ",") {
569			if e = strings.TrimSpace(e); e != "" {
570				opts.Env = append(opts.Env, e)
571			}
572		}
573		// Volume mounts: comma-separated vol:/path entries
574		for v := range strings.SplitSeq(f.volInput.Value(), ",") {
575			if v = strings.TrimSpace(v); v != "" {
576				opts.Volumes = append(opts.Volumes, v)
577			}
578		}
579		if len(f.networks) > 0 {
580			opts.Network = f.networks[f.networkIdx]
581		}
582		return f, func() tea.Msg { return LaunchFormSubmitMsg{Opts: opts} }
583	}
